const fs=require('fs');
const p='src/scene3d.js';
let s=fs.readFileSync(p,'utf8');
['EffectComposer','RenderPass','ShaderPass','UnrealBloomPass'].forEach(n=>{s=s.replace(new RegExp("import \\{ "+n+" \\} from 'three/addons/postprocessing/"+n+"\\.js';\\n"),'')});
let a=s.indexOf('  const FOAM_BLOOM_LAYER = 1;\n');
let e=s.indexOf('  const controls = new OrbitControls',a);
if(a<0||e<0)throw Error('composer block');
s=s.slice(0,a)+s.slice(e);
s=s.replace('    bloomComposer.setSize(width, height);\n    finalComposer.setSize(width, height);\n','');
let old=`    const previousLayerMask = camera.layers.mask;\n    camera.layers.set(FOAM_BLOOM_LAYER);\n    bloomRenderPass.camera = camera;\n    bloomComposer.render();\n    camera.layers.set(0);\n    finalRenderPass.camera = camera;\n    finalComposer.render();\n    camera.layers.mask = previousLayerMask;`;
if(!s.includes(old))throw Error('loop');
s=s.replace(old,'    renderer.render(scene, camera);');
s=s.replace('      const raw = new THREE.Group();\n      const haloContourGroup = new THREE.Group();\n      let meshCount = 0;','      const raw = new THREE.Group();\n      let meshCount = 0;');
let cs=s.indexOf('          const addHaloContour = (points) => {');
let ce=s.indexOf('          meshCount += 1;',cs);
if(cs<0||ce<0)throw Error('contour');
s=s.slice(0,cs)+s.slice(ce);
let hs=s.indexOf('      const halo = haloContourGroup;');
let he=s.indexOf('      visualRoot.add(halo);',hs);
if(hs<0||he<0)throw Error('halo place');
he+= '      visualRoot.add(halo);'.length;
const repl=`      const haloCanvas = document.createElement('canvas');\n      haloCanvas.width = 512; haloCanvas.height = 256;\n      const haloCtx = haloCanvas.getContext('2d');\n      const haloImage = new Image();\n      haloImage.onload = () => {\n        haloCtx.clearRect(0,0,512,256);\n        haloCtx.filter = 'blur(14px)';\n        haloCtx.globalAlpha = 0.9;\n        haloCtx.drawImage(haloImage,24,24,464,208);\n        haloCtx.filter = 'none';\n        haloCtx.globalCompositeOperation = 'source-in';\n        haloCtx.fillStyle = '#ffffff';\n        haloCtx.fillRect(0,0,512,256);\n        haloCtx.globalCompositeOperation = 'source-over';\n        const texture = new THREE.CanvasTexture(haloCanvas);\n        texture.colorSpace = THREE.SRGBColorSpace;\n        texture.generateMipmaps = false;\n        const halo = new THREE.Mesh(new THREE.PlaneGeometry(widthM * 1.10, heightM * 1.18), new THREE.MeshBasicMaterial({map:texture,transparent:true,opacity:0.72,depthWrite:false,toneMapped:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide}));\n        halo.position.set(0,0,-Math.max(0.004,wallGapM*0.68));\n        halo.raycast=()=>{};\n        visualRoot.add(halo);\n      };\n      haloImage.src = assetUrl;`;
s=s.slice(0,hs)+repl+s.slice(he);
fs.writeFileSync(p,s);
